CREATE TABLE app_meta(key TEXT PRIMARY KEY,value TEXT NOT NULL);
CREATE TABLE settings(id INTEGER PRIMARY KEY CHECK(id=1),version INTEGER NOT NULL DEFAULT 1,data TEXT NOT NULL CHECK(json_valid(data)),pending_retention TEXT CHECK(pending_retention IS NULL OR json_valid(pending_retention)),updated_at INTEGER NOT NULL);
CREATE TABLE hours(location TEXT PRIMARY KEY CHECK(location='bel_air'),version INTEGER NOT NULL DEFAULT 1,timezone TEXT NOT NULL CHECK(timezone='America/New_York'),days TEXT NOT NULL CHECK(json_valid(days)),updated_at INTEGER NOT NULL);
CREATE TABLE members(id TEXT PRIMARY KEY,email_norm TEXT NOT NULL UNIQUE,google_sub TEXT UNIQUE,role TEXT NOT NULL CHECK(role IN ('admin','viewer')),active INTEGER NOT NULL DEFAULT 1 CHECK(active IN (0,1)),version INTEGER NOT NULL DEFAULT 1,bound_at INTEGER,joined_at INTEGER NOT NULL,updated_at INTEGER NOT NULL);
CREATE TABLE sessions(sid_hash TEXT PRIMARY KEY,csrf_hash TEXT NOT NULL,member_id TEXT REFERENCES members(id),member_version INTEGER,created_at INTEGER NOT NULL,last_seen_at INTEGER NOT NULL,absolute_expires_at INTEGER NOT NULL,idle_expires_at INTEGER NOT NULL,revoked_at INTEGER,auth_method TEXT NOT NULL CHECK(auth_method IN ('anonymous','google')));
CREATE INDEX sessions_expiry ON sessions(absolute_expires_at);
CREATE TABLE invitations(id TEXT PRIMARY KEY,token_hash TEXT NOT NULL UNIQUE,encrypted_token TEXT,email_norm TEXT NOT NULL,role TEXT NOT NULL CHECK(role IN ('admin','viewer')),creator_id TEXT NOT NULL REFERENCES members(id),created_at INTEGER NOT NULL,expires_at INTEGER NOT NULL,accepted_at INTEGER,accepted_by TEXT REFERENCES members(id),revoked_at INTEGER,version INTEGER NOT NULL DEFAULT 1);
CREATE INDEX invitations_expiry ON invitations(expires_at);
CREATE TABLE oauth_states(state_hash TEXT PRIMARY KEY,sid_hash TEXT NOT NULL REFERENCES sessions(sid_hash),purpose TEXT NOT NULL CHECK(purpose IN ('login','gmail')),payload_cipher TEXT NOT NULL,member_id TEXT REFERENCES members(id),member_version INTEGER,invite_hash TEXT,connection_version INTEGER,return_to TEXT NOT NULL,expires_at INTEGER NOT NULL,consumed_at INTEGER);
CREATE INDEX oauth_expiry ON oauth_states(expires_at);
CREATE TABLE requests(id TEXT PRIMARY KEY,reference_hash TEXT NOT NULL UNIQUE,reference_cipher TEXT NOT NULL,status_token_hash TEXT NOT NULL UNIQUE,status_token_cipher TEXT NOT NULL,source TEXT NOT NULL CHECK(source IN ('online','walk_in')),data_mode TEXT NOT NULL CHECK(data_mode IN ('demo','operational')),is_synthetic INTEGER NOT NULL DEFAULT 0 CHECK(is_synthetic IN (0,1)),version INTEGER NOT NULL DEFAULT 1,status TEXT NOT NULL CHECK(status IN ('new','reviewing','estimate_sent','needs_visit','not_repairable','awaiting_dropoff','in_shop','in_progress','ready','picked_up','cancelled')),item_type TEXT NOT NULL CHECK(item_type IN ('shoes','boots','handbag_purse','belt_strap','leather_garment','luggage','baseball_glove','other_leather','keys')),work_types TEXT NOT NULL CHECK(json_valid(work_types)),description TEXT NOT NULL,brand_age TEXT,needed_by TEXT,contact_name TEXT NOT NULL,email_norm TEXT,phone_e164 TEXT,preferred TEXT NOT NULL CHECK(preferred IN ('email','call','text')),callback_phone TEXT,dropoff_location TEXT NOT NULL CHECK(dropoff_location IN ('bel_air','dundalk')),pickup_location TEXT NOT NULL CHECK(pickup_location IN ('bel_air','dundalk')),repair_location TEXT NOT NULL DEFAULT 'bel_air' CHECK(repair_location='bel_air'),customer_message TEXT,current_offer_id TEXT REFERENCES offers(id),created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL,closed_at INTEGER,consent_version TEXT,accepted_at INTEGER,CHECK((status IN ('picked_up','cancelled'))=(closed_at IS NOT NULL)));
CREATE INDEX requests_status ON requests(status,created_at DESC,id);
CREATE INDEX requests_location ON requests(dropoff_location,status,created_at DESC,id);
CREATE INDEX requests_closed ON requests(closed_at) WHERE closed_at IS NOT NULL;
CREATE INDEX requests_email ON requests(email_norm);
CREATE INDEX requests_phone ON requests(phone_e164);
CREATE INDEX requests_name ON requests(contact_name);
CREATE TABLE drafts(id TEXT PRIMARY KEY,token_hash TEXT NOT NULL UNIQUE,sid_hash TEXT NOT NULL,created_at INTEGER NOT NULL,expires_at INTEGER NOT NULL,state TEXT NOT NULL CHECK(state IN ('active','submitted','deleted')),request_id TEXT REFERENCES requests(id),receipt_cipher TEXT);
CREATE INDEX drafts_expiry ON drafts(expires_at);
CREATE TABLE photos(id TEXT PRIMARY KEY,draft_id TEXT NOT NULL REFERENCES drafts(id),request_id TEXT REFERENCES requests(id),state TEXT NOT NULL CHECK(state IN ('uploading','processing','ready','rejected','deleted','unavailable')),slot INTEGER NOT NULL CHECK(slot BETWEEN 0 AND 4),raw_key TEXT,sanitized_key TEXT,source_sha256 TEXT,output_sha256 TEXT,bytes INTEGER,width INTEGER,height INTEGER,media_type TEXT,error_code TEXT,created_at INTEGER NOT NULL,ready_at INTEGER,attached_at INTEGER,deleted_at INTEGER,processing_lease TEXT,lease_expires_at INTEGER,CHECK(request_id IS NULL OR attached_at IS NOT NULL));
CREATE UNIQUE INDEX photos_live_slot ON photos(draft_id,slot) WHERE state<>'deleted';
CREATE INDEX photos_request ON photos(request_id,state);
CREATE INDEX photos_cleanup ON photos(state,created_at);
CREATE TABLE offers(id TEXT PRIMARY KEY,request_id TEXT NOT NULL REFERENCES requests(id),kind TEXT NOT NULL CHECK(kind IN ('estimate','visit')),state TEXT NOT NULL CHECK(state IN ('active','answered','superseded')),currency TEXT NOT NULL DEFAULT 'USD' CHECK(currency='USD'),amount_min INTEGER,amount_max INTEGER,scope TEXT NOT NULL,timing_note TEXT,customer_message TEXT,created_by TEXT NOT NULL REFERENCES members(id),created_at INTEGER NOT NULL,version INTEGER NOT NULL DEFAULT 1,CHECK((kind='visit' AND amount_min IS NULL AND amount_max IS NULL) OR (kind='estimate' AND amount_min BETWEEN 1 AND 100000000 AND (amount_max IS NULL OR amount_max BETWEEN amount_min AND 100000000))));
CREATE UNIQUE INDEX offers_active ON offers(request_id) WHERE state='active';
CREATE INDEX offers_request ON offers(request_id,created_at,id);
CREATE TABLE customer_responses(id TEXT PRIMARY KEY,request_id TEXT NOT NULL REFERENCES requests(id),offer_id TEXT NOT NULL UNIQUE REFERENCES offers(id),choice TEXT NOT NULL CHECK(choice IN ('accept','decline','request_call')),callback_phone TEXT,created_at INTEGER NOT NULL);
CREATE TABLE request_events(id TEXT PRIMARY KEY,request_id TEXT NOT NULL REFERENCES requests(id),type TEXT NOT NULL,from_status TEXT,status TEXT NOT NULL,public_message TEXT,visibility TEXT NOT NULL CHECK(visibility IN ('customer','internal')),actor_id TEXT REFERENCES members(id),reason TEXT,related_offer_id TEXT REFERENCES offers(id),request_version INTEGER NOT NULL,created_at INTEGER NOT NULL);
CREATE INDEX events_request ON request_events(request_id,created_at,id);
CREATE TABLE notes(id TEXT PRIMARY KEY,request_id TEXT NOT NULL REFERENCES requests(id),author_id TEXT NOT NULL REFERENCES members(id),text TEXT NOT NULL,created_at INTEGER NOT NULL,request_version INTEGER NOT NULL);
CREATE INDEX notes_request ON notes(request_id,created_at,id);
CREATE TABLE notices(id TEXT PRIMARY KEY,version INTEGER NOT NULL DEFAULT 1,locations TEXT NOT NULL CHECK(json_valid(locations)),message TEXT NOT NULL,reopen_text TEXT,starts_at INTEGER NOT NULL,ends_at INTEGER NOT NULL,created_by TEXT NOT NULL REFERENCES members(id),updated_by TEXT NOT NULL REFERENCES members(id),created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL,deleted_at INTEGER,CHECK(ends_at>starts_at));
CREATE INDEX notices_time ON notices(starts_at,ends_at,deleted_at,updated_at);
